<template>
  <section class="tutorial-editor">
    <header class="page-head"><div><small>LINEAR FLOW ORCHESTRATOR</small><h1>{{ model.flow.name || flowId }}</h1><p>{{ flowId }} · {{ source==='draft'?'MySQL 草稿':'正式 Tutorial Snapshot' }}</p></div><a-space wrap><a-button @click="router.push('/content/tutorials')">返回列表</a-button><a-button @click="validateAll">完整校验</a-button><a-button type="primary" :disabled="readonly" @click="save">保存草稿</a-button></a-space></header>
    <a-alert v-if="conflict" type="error" show-icon message="CONTENT_CONFLICT / rowVersion 409" description="服务端版本已变化；本地未保存内容仍保留，可刷新后重新合并。"/>
    <div class="source-bar"><b>预览数据源</b><a-radio-group :value="source" button-style="solid" @change="changeSource"><a-radio-button value="draft">草稿</a-radio-button><a-radio-button value="published">已发布</a-radio-button></a-radio-group><span v-if="dirty">● 未保存</span><em v-else>已同步</em></div>
    <div v-if="source==='published' && published.mode==='LEGACY_FALLBACK'" class="legacy"><strong>LEGACY_FALLBACK</strong><h2>当前正式版本未启用新手引导</h2><p>R000007 未声明 Tutorial Snapshot；小游戏保持现有启动流程，且本页不会显示 MySQL 草稿步骤。</p><code>{{ published.reason }}</code><a-button @click="changeSource({target:{value:'draft'}})">返回草稿</a-button></div>
    <div v-else class="editor-grid">
      <aside class="step-rail"><header><a-button type="link" size="small" @click="selectedId=''">Flow 设置</a-button><a-button size="small" :disabled="readonly" @click="addStep">新增步骤</a-button></header><button v-for="(step,index) in model.steps" :key="step.id" :class="{active:selectedId===step.id,missing:isMissing(step)}" @click="selectedId=step.id"><i>{{ String(index+1).padStart(2,'0') }}</i><span><b>{{ step.title }}</b><small>{{ step.id }}</small></span><em>{{ step.targetType }}</em></button><a-empty v-if="!model.steps.length" description="尚无步骤"/></aside>
      <main class="sequence"><div class="sequence-tools"><b>顺序编排</b><a-space><a-button size="small" :disabled="readonly||!selected" @click="duplicateStep">复制步骤</a-button><a-button size="small" :disabled="readonly||!canMove(-1)" @click="moveStep(-1)">上移</a-button><a-button size="small" :disabled="readonly||!canMove(1)" @click="moveStep(1)">下移</a-button><a-popconfirm title="删除前检查下一步骤、分支与功能规则引用。" @confirm="deleteStep"><a-button size="small" danger :disabled="readonly||!selected">删除步骤</a-button></a-popconfirm></a-space></div>
        <div class="flow-line"><article v-for="(step,index) in model.steps" :key="step.id" :class="{selected:selectedId===step.id,forced:step.force,missing:isMissing(step)}" @click="selectedId=step.id"><div><small>STEP {{ index+1 }}</small><a-tag v-if="step.force" color="red">强制步骤</a-tag><a-tag v-if="isMissing(step)" color="orange">Missing</a-tag></div><h3>{{ step.title }}</h3><p>{{ step.body }}</p><footer><code>{{ step.triggerType }}</code><span>→ {{ step.nextStepId || 'END' }}</span></footer></article></div>
        <TutorialPreviewPanel title="单步预览 · 完整 Flow 预览" :snapshot="previewSnapshot" :scenario="scenario" :source-label="source==='draft'?'草稿模拟':'正式只读'" @scenario="setScenario" @single="previewSingle" @full="previewFull" @missing="previewMissing" @next="previewNext" @skip="previewSkip"/>
      </main>
      <aside class="inspector" v-if="selected"><header><small>STEP INSPECTOR</small><h2>{{ selected.title }}</h2></header><a-form layout="vertical"><a-form-item label="步骤 ID"><a-input v-model:value="selected.id" disabled/></a-form-item><a-form-item label="标题"><a-input v-model:value="selected.title" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="正文"><a-textarea v-model:value="selected.body" :rows="3" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="角色名"><a-input v-model:value="selected.characterName" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="头像 Art Key"><ArtResourceField v-model="selected.avatarArtKey" label="引导头像" resource-type="tutorial" :disabled="readonly" @update:model-value="changed"/></a-form-item>
        <div class="two"><a-form-item label="触发条件"><a-select v-model:value="selected.triggerType" :options="triggerOptions" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="完成条件"><a-select v-model:value="selected.completionType" :options="completionOptions" :disabled="readonly" @change="changed"/></a-form-item></div>
        <a-form-item label="稳定目标"><a-select v-model:value="selected.targetId" show-search option-filter-prop="label" :options="targetOptions" :disabled="readonly" @change="targetChanged"/></a-form-item><div class="target-diagnostic" :class="{missing:isMissing(selected)}"><b>{{ isMissing(selected)?'Missing警告':'当前可解析' }}</b><span>页面 {{ targetMeta.page }} · {{ targetMeta.type }} · 预览位置 {{ targetMeta.position }}</span><small>备用目标：{{ selected.fallbackAction || '未配置' }}</small></div>
        <div class="two"><a-form-item label="目标类型"><a-select v-model:value="selected.targetType" :options="targetTypes" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="备用目标"><a-select v-model:value="selected.fallbackAction" :options="fallbackOptions" :disabled="readonly" @change="changed"/></a-form-item></div><div class="two"><a-form-item label="下一步骤"><a-select v-model:value="selected.nextStepId" allow-clear :options="stepOptions" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="跳过分支"><a-select v-model:value="selected.skipStepId" allow-clear :options="stepOptions" :disabled="readonly" @change="changed"/></a-form-item></div>
        <div class="two"><a-form-item label="超时 ms"><a-input-number v-model:value="selected.timeoutMs" :min="0" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="自动关闭 ms"><a-input-number v-model:value="selected.triggerConfig.autoCloseMs" :min="0" :disabled="readonly" @change="changed"/></a-form-item></div><a-form-item label="引导箭头 Art Key"><ArtResourceField v-model="selected.arrow.artKey" label="引导箭头" resource-type="tutorial" :disabled="readonly" @update:model-value="changed"/></a-form-item><div class="two"><a-form-item label="箭头方向"><a-select v-model:value="selected.arrow.direction" :options="arrowOptions" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="步骤解锁功能"><a-select v-model:value="selected.featureId" allow-clear :options="featureOptions" :disabled="readonly" @change="changed"/></a-form-item></div><div class="two"><a-form-item label="遮罩透明度"><a-slider v-model:value="selected.mask.opacity" :min="0" :max=".95" :step=".05" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="高亮边距"><a-input-number v-model:value="selected.mask.padding" :min="0" :disabled="readonly" @change="changed"/></a-form-item></div><a-space wrap><a-checkbox v-model:checked="selected.blockInput" :disabled="readonly" @change="changed">限制输入</a-checkbox><a-checkbox v-model:checked="selected.force" :disabled="readonly" @change="changed">强制步骤</a-checkbox><a-checkbox v-model:checked="selected.terminal" :disabled="readonly" @change="changed">终点</a-checkbox><a-checkbox v-model:checked="selected.triggerConfig.allowBlankContinue" :disabled="readonly" @change="changed">允许点击空白继续</a-checkbox></a-space>
        <section class="unlock-rules"><header><b>功能解锁配置</b><a-button size="small" :disabled="readonly" @click="addUnlockRule">添加规则</a-button></header><article v-for="rule in selectedRules" :key="rule.id"><a-select v-model:value="rule.featureId" :options="featureOptions" :disabled="readonly" @change="changed"/><a-select v-model:value="rule.unlockTrigger" :options="unlockTriggerOptions" :disabled="readonly" @change="changed"/><a-checkbox v-model:checked="rule.unlockOnSkip" :disabled="readonly" @change="changed">跳过时解锁</a-checkbox><a-button danger size="small" :disabled="readonly" @click="removeUnlockRule(rule.id)">删除</a-button></article></section>
      </a-form></aside>
      <aside v-else class="inspector flow-inspector"><header><small>FLOW SETTINGS</small><h2>流程属性</h2></header><a-form layout="vertical"><a-form-item label="名称"><a-input v-model:value="model.flow.name" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="说明"><a-textarea v-model:value="model.flow.description" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="起始条件"><a-input v-model:value="model.flow.startCondition.type" :disabled="readonly" @change="changed"/></a-form-item><a-form-item label="安全跳过解锁"><a-select v-model:value="model.flow.skipUnlockFeatures" mode="multiple" :options="featureOptions" :disabled="readonly" @change="changed"/></a-form-item><a-checkbox v-model:checked="model.flow.skippable" :disabled="readonly" @change="changed">允许跳过（运行时二次确认）</a-checkbox><a-checkbox v-model:checked="model.flow.allowReplay" :disabled="readonly" @change="changed">允许教学重放</a-checkbox></a-form><a-button type="link" @click="selectedId=model.steps[0]?.id">选择第一步</a-button></aside>
    </div>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue';
import { onBeforeRouteLeave, useRoute, useRouter } from 'vue-router';
import { message, Modal } from 'ant-design-vue';
import { contentApi } from '../../api/content';
import ArtResourceField from '../../components/art-resource/ArtResourceField.vue';
import TutorialPreviewPanel from './tutorial-editor/TutorialPreviewPanel.vue';
import { TutorialPreviewSimulator } from './tutorial-editor/TutorialPreviewSimulator';

const route=useRoute(); const router=useRouter(); const flowId=String(route.params.flowId);
const source=ref<'draft'|'published'>('draft'); const model=reactive<any>(blank()); const published=reactive<any>({});
const targets=ref<any[]>([]); const features=ref<any[]>([]); const selectedId=ref(''); const dirty=ref(false); const conflict=ref<any>(); const scenario=ref('fresh');
let simulator=new TutorialPreviewSimulator([]); const previewSnapshot=ref(simulator.snapshot);
const readonly=computed(()=>source.value==='published'); const selected=computed(()=>model.steps.find((step:any)=>step.id===selectedId.value));
const stepOptions=computed(()=>model.steps.filter((step:any)=>step.id!==selectedId.value).map((step:any)=>({value:step.id,label:step.title})));
const targetOptions=computed(()=>targets.value.map(target=>({value:target.id,label:`${pageOf(target.id)} · ${target.name} · ${target.type} · 可解析`})));
const featureOptions=computed(()=>features.value.map(feature=>({value:feature.id,label:`${feature.name}${feature.safeOnSkip?' · 可安全跳过解锁':''}`})));
const selectedRules=computed(()=>model.unlockRules.filter((rule:any)=>rule.stepId===selectedId.value));
const targetMeta=computed(()=>{const target=targets.value.find(item=>item.id===selected.value?.targetId);return{page:pageOf(target?.id),type:target?.type??selected.value?.targetType??'-',position:positionOf(target?.id)}});
const triggerOptions=options(['app-first-launch','campaign-page-opened','chapter-map-opened','stage-detail-opened','stage-started','battle.ready','player-moved','player-attacked','enemy-defeated','wave-cleared','stage-cleared','settlement-opened','reward-granted','equipment-page-opened','equipment-equipped','tutorial-step-completed']);
const completionOptions=options(['dialog.acknowledged','target.click','stage-started','player-moved','player-attacked','enemy-defeated','wave-cleared','stage-cleared','reward-granted','equipment-equipped','tutorial-step-completed']);
const targetTypes=options(['ui','canvas','stage','campaign','art','feature']); const fallbackOptions=options(['skip-step','continue-without-target','retry','end-flow']); const arrowOptions=options(['up','down','left','right','auto']);
const unlockTriggerOptions=options(['tutorial-step-completed','stage-cleared','reward-granted','equipment-equipped','flow-completed']);

onMounted(loadDraft); onBeforeUnmount(disposePreview);
onBeforeRouteLeave((_to,_from,next)=>{if(!dirty.value)return next();Modal.confirm({title:'存在未保存修改',content:'离开后本地步骤编排会丢失。',okText:'放弃修改',cancelText:'继续编辑',onOk:()=>next(),onCancel:()=>next(false)});});

async function loadDraft(){const [data,targetRows,featureRows]=await Promise.all([contentApi.tutorialFlow(flowId),contentApi.tutorialTargets(),contentApi.tutorialFeatures()]);targets.value=targetRows;features.value=featureRows;assignModel(data);dirty.value=false;conflict.value=undefined;resetPreview();}
async function loadPublished(){const data=await contentApi.publishedTutorial();Object.assign(published,data);if(data.mode==='PUBLISHED'){const flow=data.flows.find((item:any)=>item.id===flowId)??data.flows[0];assignModel(flow?{...flow,flow}:blank());}else assignModel(blank());dirty.value=false;resetPreview();}
async function changeSource(event:any){disposePreview();selectedId.value='';source.value=event.target.value;if(source.value==='published')await loadPublished();else await loadDraft();}
async function save(){try{const result=await contentApi.saveTutorialOrchestration(flowId,copy(model));assignModel(result);dirty.value=false;conflict.value=undefined;message.success(`引导草稿已保存，rowVersion ${model.flow.rowVersion}`);}catch(error:any){const data=error?.response?.data;if(data?.code==='CONTENT_CONFLICT'){conflict.value=data;message.error('rowVersion 409：本地修改已保留');return;}message.error(data?.message??data?.code??'保存失败');}}
async function validateAll(){try{const result=await contentApi.validate();result.valid?message.success(`完整校验通过：${result.warnings?.length??0} warning`):message.error(`完整校验失败：${result.errors?.length??0} error`);}catch{message.error('完整校验请求失败');}}
function addStep(){const id=`tutorial.step.${Date.now()}`;const step={id,flowId,order:model.steps.length+1,name:'新步骤',title:'新教学步骤',body:'请完成目标操作',characterName:'喵喵教官',avatarArtKey:null,triggerType:'tutorial-step-completed',triggerConfig:{},displayType:'dialog',targetType:'ui',targetId:'home.campaign',mask:{opacity:.7,padding:12},arrow:{artKey:null,direction:'auto'},blockInput:true,force:false,completionType:'target.click',completionConfig:{},timeoutMs:8000,fallbackAction:'skip-step',nextStepId:null,skipStepId:null,stageId:null,campaignId:null,featureId:null,terminal:true,enabled:true,contentVersion:1,rowVersion:0};if(model.steps.length){const tail=model.steps.at(-1);tail.nextStepId=id;tail.terminal=false;}model.steps.push(step);model.flow.startStepId??=id;model.flow.endStepId=id;selectedId.value=id;changed();}
function duplicateStep(){if(!selected.value)return;const current=selected.value;const index=model.steps.indexOf(current);const id=`${current.id}.copy${Date.now()}`;const clone={...copy(current),id,name:`${current.name} 副本`,title:`${current.title} 副本`,rowVersion:0};current.nextStepId=id;current.terminal=false;model.steps.splice(index+1,0,clone);relink();selectedId.value=id;changed();}
function deleteStep(){if(!selected.value||model.steps.length<=1)return message.warning('Flow 至少保留一个步骤');const id=selected.value.id;model.steps.splice(model.steps.indexOf(selected.value),1);model.transitions=model.transitions.filter((item:any)=>item.fromStepId!==id&&item.toStepId!==id);model.unlockRules=model.unlockRules.filter((item:any)=>item.stepId!==id);relink();selectedId.value=model.steps[0]?.id??'';changed();}
function moveStep(delta:number){if(!selected.value)return;const index=model.steps.indexOf(selected.value);const next=index+delta;if(next<0||next>=model.steps.length)return;[model.steps[index],model.steps[next]]=[model.steps[next],model.steps[index]];relink();changed();}
function canMove(delta:number){if(!selected.value)return false;const index=model.steps.indexOf(selected.value);return index+delta>=0&&index+delta<model.steps.length;}
function addUnlockRule(){if(!selected.value)return;model.unlockRules.push({id:`tutorial.rule.${Date.now()}`,flowId,stepId:selected.value.id,stageId:null,featureId:features.value[0]?.id??'feature.campaign',unlockTrigger:'tutorial-step-completed',condition:{},unlockOnSkip:false,order:model.unlockRules.length,enabled:true,rowVersion:0});changed();}
function removeUnlockRule(id:string){model.unlockRules=model.unlockRules.filter((rule:any)=>rule.id!==id);changed();}
function relink(){model.steps.forEach((step:any,index:number)=>{step.order=index+1;step.nextStepId=model.steps[index+1]?.id??null;step.terminal=index===model.steps.length-1;});model.flow.startStepId=model.steps[0]?.id??null;model.flow.endStepId=model.steps.at(-1)?.id??null;}
function changed(){if(readonly.value)return;dirty.value=true;resetPreview();}
function targetChanged(){if(selected.value){const target=targets.value.find(item=>item.id===selected.value.targetId);selected.value.targetType=target?.type??selected.value.targetType;}changed();}
function isMissing(step:any){return Boolean(step?.targetId)&&!targets.value.some(target=>target.id===step.targetId);}
function resetPreview(){simulator.dispose();simulator=new TutorialPreviewSimulator(model.steps,targets.value.map(item=>item.id));previewSnapshot.value=simulator.snapshot;}
function disposePreview(){previewSnapshot.value=simulator.dispose();}
function setScenario(value:string){scenario.value=value;previewSnapshot.value=simulator.startFlow(value);}
function previewSingle(){if(selected.value)previewSnapshot.value=simulator.previewStep(selected.value.id);else message.info('请先选择步骤');}
function previewFull(){previewSnapshot.value=simulator.startFlow(scenario.value);}
function previewMissing(){const step={...(selected.value??model.steps[0]??{}),id:'preview.missing-target',title:'目标解析失败',body:'当前目标不可用，按备用策略安全继续。',targetId:'preview.__missing__',fallbackAction:'skip-step'};simulator.dispose();simulator=new TutorialPreviewSimulator([step],targets.value.map(item=>item.id));previewSnapshot.value=simulator.startFlow('fresh');}
function previewNext(){previewSnapshot.value=simulator.next();}
function previewSkip(){previewSnapshot.value=simulator.skip();}
function assignModel(data:any){const flow=data.flow??data;const steps=copy(data.steps??[]).map((step:any)=>({...step,triggerConfig:step.triggerConfig??{},mask:step.mask??{},arrow:{artKey:null,...(step.arrow??{})}}));Object.assign(model,{flow:{...copy(flow),startCondition:flow.startCondition??{}},steps,transitions:copy(data.transitions??[]),unlockRules:copy(data.unlockRules??[])});selectedId.value=steps[0]?.id??'';}
function blank(){return{flow:{id:flowId,name:'引导 Flow',description:'',campaignId:null,startStepId:null,endStepId:null,startCondition:{},audience:{},playerCondition:{},skipUnlockFeatures:[],skippable:true,allowReplay:false,priority:0,enabled:false,schemaVersion:1,contentVersion:1,rowVersion:1},steps:[],transitions:[],unlockRules:[]};}
function copy<T>(value:T):T{return JSON.parse(JSON.stringify(value));} function options(values:string[]){return values.map(value=>({value,label:value}));}
function pageOf(id?:string){if(!id)return'-';if(id.startsWith('home.'))return'首页';if(id.startsWith('campaign.'))return'章节地图';if(id.startsWith('stage.detail'))return'关卡详情';if(id.startsWith('battle.'))return'战斗Canvas';if(id.startsWith('result.'))return'结算页';return'业务对象';}
function positionOf(id?:string){const map:Record<string,string>={'home.campaign':'底部主导航','campaign.chapter.1':'左上章节卡','campaign.stage.1-1':'地图起始节点','stage.detail.start':'详情页底部','battle.move-zone':'Canvas左下','battle.attack':'Canvas右下','result.continue':'结算页底部'};return map[id??'']??'由运行时解析器定位';}
</script>

<style scoped>
.tutorial-editor{--ink:#dcebed;--muted:#7899a7;min-width:0;padding:18px;color:var(--ink);background:radial-gradient(circle at 50% 0,#18394a 0,#071019 40%,#050a0f 100%)}
.page-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;padding:8px 2px 14px;border-bottom:1px solid #284556}.page-head small,.inspector header small{color:#55d9c6;font:700 10px Consolas,monospace;letter-spacing:.2em}.page-head h1{margin:3px 0;color:#f3faf9;font-size:27px}.page-head p{margin:0;color:var(--muted);font:11px Consolas,monospace}.source-bar{display:flex;align-items:center;gap:18px;margin:12px 0;padding:10px 12px;background:#0d1b25;border:1px solid #294352}.source-bar span{margin-left:auto;color:#ff775d;font:11px Consolas,monospace}.source-bar em{margin-left:auto;color:#62d7c0;font-style:normal}.legacy{display:grid;justify-items:start;gap:12px;min-height:390px;place-content:center;padding:50px;background:#09151f;border:1px solid #304b5b}.legacy strong{color:#ffbc61;font:700 22px Consolas,monospace}.legacy h2,.legacy p{margin:0}.legacy p{max-width:640px;color:#8eaab4}.legacy code{color:#d8a768}
.editor-grid{display:grid;grid-template-columns:230px minmax(520px,1fr) 350px;gap:13px;align-items:start}.step-rail,.inspector{position:sticky;top:12px;max-height:calc(100vh - 30px);overflow:auto;padding:13px;background:#0a1720e8;border:1px solid #263f50;box-shadow:0 12px 36px #0005}.step-rail>header,.sequence-tools{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:11px}.step-rail>button{display:flex;width:100%;align-items:center;gap:8px;margin:4px 0;padding:9px;color:#a9c4cb;text-align:left;background:transparent;border:1px solid transparent;cursor:pointer}.step-rail>button:hover,.step-rail>button.active{color:#fff;background:#182d39;border-color:#3b6575}.step-rail>button.missing{border-color:#7e4e2e}.step-rail i{color:#56cdbb;font:11px Consolas,monospace;font-style:normal}.step-rail span{min-width:0;flex:1}.step-rail span b,.step-rail span small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.step-rail span small{color:#648795;font:9px Consolas,monospace}.step-rail em{color:#78a5af;font:9px Consolas,monospace;font-style:normal}
.sequence{display:grid;min-width:0;gap:13px}.sequence-tools{padding:11px 13px;background:#0d1a23;border:1px solid #294351}.flow-line{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px}.flow-line article{position:relative;min-height:150px;padding:13px;background:#0b1a24;border:1px solid #284554;cursor:pointer}.flow-line article:after{position:absolute;right:-9px;top:50%;z-index:2;color:#58c7b8;content:'›'}.flow-line article:last-child:after{content:''}.flow-line article.selected{border-color:#61d8c4;box-shadow:inset 0 0 0 1px #61d8c4}.flow-line article.forced{border-top-color:#e66a52}.flow-line article.missing{background:#26160f;border-color:#a65c31}.flow-line article h3{margin:8px 0 5px;color:#e9f8f6}.flow-line article p{min-height:38px;margin:0;color:#87a7b1;font-size:12px}.flow-line article footer{display:flex;justify-content:space-between;gap:8px;margin-top:12px;color:#72a6b1;font-size:10px}.flow-line code{color:#f0b667}
